pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address bogusLog) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // Adversarial/functional counterparty: a real log-like contract whose
        // address, if it ever got stored, would make Put's AddMessage call succeed.
        FakeLog lg = new FakeLog();

        // Before initialization, setting the log is allowed (same in P and M).
        vm.prank(actor);
        c.SetLogFile(address(lg));

        // Lock the configuration.
        c.Initialized();

        // After initialization, SetLogFile(_log) must have NO observable effect:
        // it must revert AND leave c's log configuration untouched.
        bool okSet;
        try c.SetLogFile(bogusLog) { okSet = true; } catch { okSet = false; }

        // Observable consequence of an unchanged log: a Put must still revert
        // (the effective log remains the original zero/old one, so AddMessage fails).
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool okPut;
        try c.Put{value: 1 wei}(0) { okPut = true; } catch { okPut = false; }

        assertTrue(!okSet && !okPut);
    }
}

// Minimal log-like counterparty used only as an address for c's external AddMessage call.
contract FakeLog {
    function AddMessage(address, uint, string calldata) external pure {}
}

